mat2 rot(float a) { float s = sin(a), c = cos(a); return mat2(c, -s, s, c); }
float map(vec3 p) {
  p.xz = rot(time * 0.5) * p.xz;
  p.xy = rot(time * 0.3) * p.xy;
  vec3 a = abs(p) - 1.0;
  float b1 = max(a.x, max(a.y, a.z));
  float b2 = max(abs(p.x)-0.92, max(abs(p.y)-0.92, abs(p.z)-0.92));
  float outer = max(b1, -b2);
  vec3 inP = p * (1.5 + 0.3 * sin(time * 2.0));
  vec3 c = abs(inP) - 0.7;
  float inner = max(max(c.x, max(c.y, c.z)), -max(abs(inP.x)-0.62, max(abs(inP.y)-0.62, abs(inP.z)-0.62)));
  return min(outer, inner);
}
shader_body {
  vec2 p = (uv - 0.5) * vec2(aspect.x, 1.0) * 2.0;
  vec3 ro = vec3(0.0, 0.0, -3.2);
  vec3 rd = normalize(vec3(p, 1.6));
  float t = 0.0;
  float laser = 0.0;
  for (int i = 0; i < 45; i++) {
    float d = map(ro + rd * t);
    laser += 0.015 / (0.06 + abs(d));
    if (d < 0.003 || t > 7.0) break;
    t += d * 0.75;
  }
  vec3 col = laser * vec3(0.0, 0.85, 1.0) * (0.8 + 0.3 * bass);
  ret = col;
}
